def kthDecodedChar(s, k):
    size = 0
    end = 0
    while end < len(s) and size < k:
        ch = s[end]
        if ch.isdigit():
            size *= int(ch)
        else:
            size += 1
        end += 1
    for i in range(end - 1, -1, -1):
        ch = s[i]
        k %= size
        if ch.isdigit():
            size //= int(ch)
        else:
            if k == 0:
                return ch
            size -= 1
    return ""
